// ---------- Dagles: techniek ----------
DAILY_LESSONS.push(
  L("Aannemen met je zwakke voet uit de lucht", "Een hoge bal met je zwakke voet aannemen is lastig, maar wel te leren.", "In een wedstrijd kies jij niet op welke voet de bal valt.", ["Kijk vroeg waar de bal valt.","Zet je zwakke voet omhoog als een kussen.","Geef mee als de bal je raakt."], "Gooi de bal 20 keer op en neem hem aan met je zwakke voet.", "Je voet stijf houden.", "Kussen, meegeven."),
  L("Aannemen terwijl je achteruit loopt", "Soms komt de bal als je net achteruit loopt.", "Dan moet je toch goed kunnen aannemen.", ["Loop achteruit met kleine stappen.","Stop vlak voor de bal komt.","Neem aan met je binnenkant."], "Laat iemand 10 ballen gooien terwijl je achteruit loopt.", "Al lopend aannemen zonder te stoppen.", "Kort stoppen, dan aannemen."),
  L("De stop-turn", "Bij de stop-turn zet je de bal stil met je zool en draai je erom heen.", "Een snelle manier om om te keren.", ["Dribbel.","Zet je zool op de bal en stap eroverheen.","Draai en neem de bal met je andere voet mee."], "Doe 10 stop-turns met beide voeten.", "Na het stoppen te langzaam draaien.", "Stop, stap over, ga."),
  L("De drag-back", "Met de drag-back trek je de bal met je zool terug en draai je weg.", "Handig als een verdediger op je af komt.", ["Zet je zool op de bal.","Trek hem terug.","Draai en ga de andere kant op."], "Doe 15 drag-backs langs een pion.", "Te ver terugtrekken.", "Kort trekken, snel draaien."),
  L("De body feint", "Met een schijnbeweging van je bovenlichaam zet je de verdediger op het verkeerde been.", "Je hoeft de bal niet eens te raken.", ["Laat je schouder één kant op zakken.","Wacht tot de verdediger reageert.","Ga met de bal de andere kant op."], "Doe 15 body feints bij een pion.", "De schijnbeweging te klein maken.", "Groot bewegen, snel weg."),
  L("De la croqueta", "Bij de croqueta tik je de bal snel van je ene voet naar je andere.", "Zo glip je tussen twee tegenstanders door.", ["Tik met je binnenkant naar je andere voet.","Neem hem mee met die voet.","Versnel."], "Doe 20 croquetas langs een pion.", "Te ver tikken.", "Klein en snel."),
  L("Hooghouden met beide voeten om en om", "Om en om hooghouden maakt beide voeten even goed.", "In een wedstrijd heb je beide voeten nodig.", ["Begin met je sterke voet.","Raak daarna je zwakke voet.","Wissel steeds af."], "Probeer 20 keer om en om hoog te houden.", "Steeds terugvallen op je sterke voet.", "Links, rechts, links."),
  L("De perfecte binnenkant-pass", "De binnenkant-pass is de belangrijkste pass in voetbal.", "Hij is zuiver en goed te controleren.", ["Standbeen naast de bal, wijzend naar je doel.","Voet in een hoek van 90 graden.","Raak het midden van de bal."], "Speel 50 binnenkant-passes tegen de muur.", "Je voet niet open draaien.", "Standbeen wijst, voet open, midden raken."),
  L("Een pass hard genoeg spelen", "Een te zachte pass wordt makkelijk onderschept.", "Een stevige pass is veiliger.", ["Kijk naar de afstand.","Speel stevig, niet zacht.","Volg door met je voet."], "Speel 30 stevige passes van 10 meter tegen de muur.", "Uit angst te zacht spelen.", "Stevig is veilig."),
  L("Een lange pass laag houden", "Een lange pass over de grond is sneller dan een hoge.", "De ontvanger kan hem makkelijker aannemen.", ["Raak de bal in het midden met je wreef.","Houd je knie boven de bal.","Volg door."], "Speel 20 lange grondpasses.", "Achterover leunen.", "Midden, knie over de bal."),
  L("Een schot met kracht", "Een hard schot raak je met je wreef en je hele lichaam.", "Kracht komt uit je heup en je zwaai.", ["Neem een aanloop.","Zwaai je been van achter de heup.","Raak de bal vol met je wreef."], "Schiet 20 harde schoten op een doel.", "Alleen vanuit je knie schieten.", "Zwaai vanuit je heup."),
  L("Afronden met je hoofd koel", "Voor het doel heb je weinig tijd, maar paniek helpt niet.", "Rust maakt je schoten beter.", ["Adem uit.","Kies een hoek.","Schiet zonder te twijfelen."], "Doe 10 afrondingen waarbij je bewust rustig blijft.", "Haasten en over schieten.", "Rustig blijven, zeker schieten."),
  L("Schieten met je voorste voet", "Soms heb je geen tijd om de bal naar je sterke voet te leggen.", "Dan schiet je met de voet die het dichtst bij is.", ["Kijk welke voet het dichtst bij is.","Zet je standbeen snel neer.","Schiet."], "Doe 15 schoten met de dichtstbijzijnde voet.", "Te veel aanrakingen om naar je sterke voet te gaan.", "Dichtstbijzijnde voet."),
  L("Verdedigen: de schouder-schouder", "In een loopduel mag je schouder tegen schouder duwen.", "Zo win je de bal netjes.", ["Kom naast de aanvaller.","Zet je schouder tegen zijn schouder.","Duw op het moment dat de bal dichtbij is."], "Oefen 10 schouderduels met een vriend.", "Met je arm of hand duwen.", "Schouder, niet hand."),
  L("Verdedigen: tussen man en doel", "Een verdediger staat altijd tussen zijn man en het doel.", "Zo kan de aanvaller niet zomaar richting doel.", ["Kijk waar je doel is.","Ga tussen je man en het doel staan.","Blijf daar als hij beweegt."], "Speel een partijtje en let alleen op je positie.", "Naast of voor je man staan.", "Man, jij, doel."),
  L("Verdedigen: niet te snel instappen", "Wie te snel instapt, wordt makkelijk uitgespeeld.", "Geduld geeft je de beste kans.", ["Kom dichtbij.","Wacht op een fout.","Stap in als de bal te ver van zijn voet is."], "Oefen 10 duels waarbij je wacht met instappen.", "Meteen naar de bal duiken.", "Geduld wint."),
  L("Een hoge bal wegkoppen", "Bij verdedigen kop je de bal hoog en ver weg.", "Hoe verder weg, hoe minder gevaar.", ["Spring op het hoogste punt.","Raak de onderkant van de bal.","Kop hem omhoog en weg."], "Laat iemand 15 hoge ballen gooien en kop ze weg.", "De bal naar beneden koppen in je eigen zestien.", "Hoog en ver weg."),
  L("Een ingooi lang en snel", "Een lange ingooi kan bijna een voorzet zijn.", "Handig dicht bij het doel van de tegenstander.", ["Neem een korte aanloop.","Buig je rug naar achteren.","Gooi met je hele lichaam."], "Gooi 15 lange ingooien.", "Een voet van de grond optillen.", "Voeten aan de grond, hele lichaam."),
  L("Een korte pass in de voeten bij druk", "Onder druk is een korte, zekere pass het best.", "Zo houd je de bal in het team.", ["Kijk naar de dichtstbijzijnde teamgenoot.","Speel kort en stevig in zijn voet.","Loop meteen weer vrij."], "Oefen 20 korte passes onder druk van een vriend.", "Een moeilijke lange bal onder druk.", "Kort, zeker, vrijlopen."),
  L("Snel spelen na een aanname", "Hoe sneller je na de aanname speelt, hoe minder tijd de tegenstander heeft.", "Snel spel maakt het verschil.", ["Kijk voor de aanname.","Neem aan naar je passrichting.","Speel met je tweede aanraking."], "Speel 3 minuten in twee keer raken tegen de muur.", "Drie of meer aanrakingen.", "Aanname, pass."),
  L("Dribbelen met tempowisseling", "Een dribbel met wisselend tempo is moeilijk te verdedigen.", "De verdediger weet niet wanneer je versnelt.", ["Dribbel rustig.","Versnel ineens.","Rem weer af."], "Dribbel 5 minuten en wissel steeds van tempo.", "Steeds even snel dribbelen.", "Langzaam, snel, langzaam."),
  L("Explosief na een kap", "Een kap werkt pas als je daarna wegsprint.", "Anders komt de verdediger terug.", ["Kap de bal.","Duw af met je buitenste been.","Sprint 5 meter."], "Doe 10 kappen gevolgd door een sprint.", "Na de kap stil staan.", "Kap en sprint."),
  L("Spelen met de buitenkant naar de vleugel", "Met je buitenkant speel je de bal snel naar de zijkant.", "Zonder je lichaam te draaien.", ["Kijk naar de vleugel.","Raak de bal met je buitenkant.","Speel hem in de loop van je teamgenoot."], "Speel 15 buitenkant-passes naar een pion opzij.", "Je lichaam eerst draaien.", "Buitenkant, niet draaien."),
  L("Afronden na een dribbel langs de keeper", "Als je de keeper hebt uitgespeeld, is het doel leeg.", "Schiet dan rustig en zeker.", ["Speel de keeper uit.","Kijk naar het doel.","Schuif de bal rustig in."], "Oefen 10 keer om een stoel heen en rustig inschieten.", "Hard schieten op een leeg doel.", "Rustig inschuiven."),
  L("De keeper laten bewegen", "Als de keeper beweegt, is hij makkelijker te verslaan.", "Een schijnschot kan helpen.", ["Doe alsof je schiet.","Kijk of de keeper gaat liggen.","Schiet langs of over hem."], "Oefen 10 schijnschoten met een vriend als keeper.", "Elke keer meteen schieten.", "Schijn, kijk, schiet."),
  L("Een snelle loopactie na een pass", "Na je pass ben je even vergeten door de tegenstander.", "Dat is het moment om weg te lopen.", ["Pass.","Sprint meteen naar voren.","Vraag de bal terug."], "Oefen 15 pass-en-sprint acties.", "Na je pass kijken waar de bal heen gaat.", "Pass en sprint."),
  L("Positie bij een aanval als verdediger", "Ook als je team aanvalt, heeft een verdediger een taak.", "Je moet klaarstaan voor een counter.", ["Blijf achter de bal.","Houd je man in de gaten.","Schuif mee op naar de middenlijn."], "Let in een partijtje op je positie bij aanvallen.", "Mee naar voren rennen als iedereen dat doet.", "Achter de bal, klaar voor de counter."),
  L("Een schot blokken", "Een schot blokken kan een goal voorkomen.", "Met je lichaam of voet in de baan van de bal.", ["Kijk naar de bal.","Zet een stap in de baan.","Houd je armen achter je rug."], "Laat een vriend 10 keer zacht schieten en blok de bal.", "Je armen omhoog doen.", "Lichaam in de baan, armen achter."),
  L("Spelen met je rug naar het doel", "Als spits krijg je de bal vaak met je rug naar het doel.", "Dan moet je de bal goed vasthouden of kaatsen.", ["Voel waar de verdediger is.","Neem de bal aan met je verste voet.","Kaats of draai als het kan."], "Oefen 10 aannames met iemand in je rug.", "Rechtop staan.", "Voelen, verste voet, kaatsen."),
  L("Bewegen voor je de bal krijgt", "Even bewegen voor de pass geeft je ruimte.", "Een stilstaande speler is makkelijk te dekken.", ["Loop een stap weg.","Kom dan terug naar de bal.","Vraag de bal."], "Oefen 15 keer een stap weg en terug voor de pass.", "Stil staan wachten op de bal.", "Weg, terug, bal."),
  L("Een penalty met de binnenkant", "Een geplaatste penalty met je binnenkant is zeker.", "Precisie is belangrijker dan kracht.", ["Kies een hoek.","Raak de bal met je binnenkant.","Speel hem stevig in de hoek."], "Neem 10 penalty's met je binnenkant.", "Te zacht schieten.", "Stevig en geplaatst."),
  L("Een volley met je binnenkant", "Een volley met je binnenkant is zuiverder dan met je wreef.", "Goed voor korte afstanden.", ["Kijk naar de bal.","Draai je voet open.","Raak de bal in het midden."], "Gooi 15 ballen op en volley met je binnenkant.", "Te hard willen.", "Open voet, midden raken."),
  L("Aannemen met je borst en draaien", "Na een borst-aanname kun je meteen draaien.", "Zo ben je weg van je tegenstander.", ["Neem aan op je borst.","Draai je lichaam mee.","Laat de bal naast je vallen."], "Gooi 15 ballen op en draai na de borst-aanname.", "Recht vooruit aannemen.", "Borst, draai, ga."),
  L("De bal op de grond houden", "Een bal op de grond is makkelijker te controleren.", "Hoge ballen geven de tegenstander kansen.", ["Speel met je binnenkant.","Houd je knie boven de bal.","Speel stevig over de grond."], "Speel 30 passes en zorg dat geen enkele stuitert.", "Onder de bal raken.", "Over de grond."),
  L("Communicatie: 'man', 'tijd', 'draai'", "Drie korte woorden die je teamgenoot veel helpen.", "Zo weet hij wat er achter hem gebeurt.", ["'Man' = er komt iemand.","'Tijd' = je hebt ruimte.","'Draai' = je kunt draaien."], "Gebruik in de volgende training alle drie de woorden.", "Niets zeggen.", "Man, tijd, draai."),
  L("Concentratie bij een spelhervatting", "Bij een spelhervatting is iedereen even stil.", "Wie dan scherp is, heeft voordeel.", ["Kijk waar de bal is.","Zoek je man of plek.","Wees klaar voor de bal."], "Let in een wedstrijd op elke spelhervatting.", "Even uitrusten bij een hervatting.", "Scherp bij elke hervatting."),
  L("Positief blijven na een tegengoal", "Na een tegengoal is het belangrijk om meteen door te gaan.", "Negatieve gedachten maken je slechter.", ["Adem uit.","Zeg iets positiefs tegen je team.","Concentreer je op de volgende actie."], "Oefen een positieve zin die je na een tegengoal zegt.", "Boos worden op teamgenoten.", "Hoofd omhoog, door."),
  L("Je energie verdelen", "Een wedstrijd duurt lang. Je moet je energie verdelen.", "Wie alles in de eerste helft geeft, heeft niets meer aan het eind.", ["Sprint als het moet.","Wandel als het kan.","Houd energie over voor de laatste minuten."], "Let in de volgende wedstrijd op wanneer je sprint en wanneer je rust.", "Steeds sprinten, ook als het niet nodig is.", "Slim sprinten."),
  L("Opwarmen voor de wedstrijd", "Een goede warming-up maakt je klaar en voorkomt blessures.", "Je spieren worden warm en je hoofd scherp.", ["Rustig joggen.","Zwaaiende bewegingen en loopjes.","Korte sprints en balcontacten."], "Doe voor je volgende wedstrijd een warming-up van 15 minuten.", "Meteen hard schieten zonder op te warmen.", "Jog, zwaai, sprint."),
  L("De afkoeling na de wedstrijd", "Na de wedstrijd koel je af zodat je sneller herstelt.", "Je spieren worden minder stijf.", ["Jog rustig 3 minuten.","Rek je benen.","Drink en eet iets."], "Doe na je volgende wedstrijd de hele afkoeling.", "Meteen gaan zitten.", "Jog, rek, drink."),
  L("Spelen met plezier", "Plezier maakt je een betere speler.", "Wie plezier heeft, leert sneller en speelt vrijer.", ["Lach om een fout.","Probeer iets nieuws.","Geniet van het spel."], "Probeer in de volgende training één nieuw trucje met plezier.", "Te veel denken aan fouten.", "Plezier eerst.")
);

